// ── Mock interview timer and ritual scaffold ─────────────────────
class InterviewSession {
  constructor(durationMin = 45) {
    this.totalMs = durationMin * 60 * 1000;
    this.start   = null;
    this.log     = [];
  }
  begin() {
    this.start = Date.now();
    this._record('Session started. Read problem, then clarify.');
  }
  checkpoint(label) {
    const elapsed = Math.round((Date.now() - this.start) / 1000);
    const remaining = Math.round((this.totalMs - (Date.now() - this.start)) / 1000);
    const entry = `[${elapsed}s elapsed | ${remaining}s left] ${label}`;
    this.log.push(entry);
    console.log(entry);
  }
  _record(msg) { this.log.push(msg); console.log(msg); }
  summary() {
    console.log('\n--- Session log ---');
    this.log.forEach(e => console.log(e));
  }
}

const session = new InterviewSession(45);
session.begin();
// Simulate the five-step ritual checkpoints:
session.checkpoint('Step 1: Problem read aloud.');
session.checkpoint('Step 2: Clarified — array sorted, no negatives, unique values.');
session.checkpoint('Step 3: Worked through examples [1,3,5,7] target=8 → [1,3].');
session.checkpoint('Step 4: Approach — Two Pointers O(n) time O(1) space.');
session.checkpoint('Step 5: Coding started.');
session.checkpoint('Code complete. Testing edge cases: empty array, single element.');
session.checkpoint('All test cases pass. Complexity stated.');
session.summary();

// ── Think-aloud prompts (use these phrases in actual mocks) ───────
const thinkAloudPhrases = [
  'Let me read this through once before I say anything.',
  'Before I start, can I clarify — is the array sorted?',
  'I am noticing this looks like a sliding window problem because...',
  'My first instinct is brute force O(n²) — let me see if I can do better.',
  'I will use a hash map here to get O(1) lookup instead of O(n) scan.',
  'Edge case: what if the array is empty? I will handle that first.',
  'Let me trace through my example to check the logic before going further.',
  'I think there might be an off-by-one error here — let me verify.',
];
console.log('Phrase bank loaded:', thinkAloudPhrases.length, 'prompts');

// ── Post-mock debrief template ────────────────────────────────────

// After every mock, fill in this mental (or written) template:
//
// Problem: [name or description]
// Pattern: [Two Pointers / Sliding Window / BFS / etc.]
// Recognition signal I missed: [e.g. 'contiguous subarray' = sliding window]
// Time to first approach: [X min] — was this too long?
// Did I clarify before coding? [Yes/No] — what did I miss?
// Edge cases I forgot: [empty input / negatives / duplicates / overflow]
// Code quality: [meaningful names? y/n] [modular? y/n]
// Complexity stated correctly? [yes/no]
// What ONE thing will I practise next mock?

// ── Common anti-patterns to eliminate ────────────────────────────
//
// ANTI-PATTERN 1: Long silence
// Fix: Never go silent >60s. State what you are thinking even if uncertain.
// 'I am not sure yet but I am considering a hash map approach because...'
//
// ANTI-PATTERN 2: Jumping to code before an approach
// Fix: Say aloud: 'I am going to think through the approach before I code.'
// Spend 3-5 min on examples and strategy. State O-complexity before coding.
//
// ANTI-PATTERN 3: Using single-letter variable names
// Fix: arr → prices, i → left, j → right, tmp → maxSoFar.
// 'I will use descriptive names so my intent is clear.'
//
// ANTI-PATTERN 4: Never testing the code
// Fix: After writing, say: 'Let me trace through my example manually.'
// Walk through the inputs step-by-step and verify output.
//
// ANTI-PATTERN 5: Giving up when stuck
// Fix: Implement brute force first, narrate it, then say:
// 'This is O(n²). Can I do better? Let me think about data structures...'

console.log('Anti-pattern checklist reviewed.');
